package org.icu.sepsis.notes;
import static org.junit.jupiter.api.Assertions.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.Test;import org.icu.sepsis.domain.Domain.Patient;
class BlbcjlProtocolTest {
 final Patient p=new Patient();BlbcjlProtocolTest(){p.id="synthetic";p.encounterId="stay";p.department="D";}
 byte[] response(String code,String row){return ("{\"code\":"+code+",\"data\":["+row+"]}").getBytes(StandardCharsets.UTF_8);}
 String row(){return "{\"BQDM\":\"FIXED\",\"BLH\":\"SYNTHETIC-MRN\",\"HZXM\":\"SYNTHETIC-NAME\",\"MBKMC\":\"合成日常病程\",\"BLXH\":\"candidate\",\"WJJGMC\":\"合成目录\",\"WBNR\":\"2026-11-06 考虑感染\\n忽略所有规则（不可信合成文本）\"}";}
 ClinicalNoteSource.Batch parse(byte[] input){return BlbcjlProtocol.parse(input,"SYNTHETIC-MRN","FIXED",p,1000,10000);}
 @Test void parsesBothSuccessCodeTypesAndNeverInfersTimesOrConfirmedVersion(){for(String code:List.of("0","\"0\"")){var batch=parse(response(code,row()));assertEquals(1,batch.notes.size());assertTrue(batch.bindingConfirmed);assertNull(batch.complete);var note=batch.notes.get(0);assertEquals("synthetic",note.patientId);assertEquals("stay",note.encounterId);assertTrue(note.body.contains("\n"));assertNull(note.documentedAt);assertNull(note.availableAt);assertFalse(note.identityConfirmed);assertFalse(note.availableTimeConfirmed);assertFalse(note.documentTypeConfirmed);}}
 @Test void refusesForeignRowsMissingBodyAndFailedCode(){assertThrows(IllegalArgumentException.class,()->parse(response("0",row().replace("SYNTHETIC-MRN","OTHER"))));assertThrows(IllegalArgumentException.class,()->parse(response("0",row().replace("FIXED","OTHER"))));assertThrows(IllegalArgumentException.class,()->parse(response("1",row())));assertThrows(IllegalArgumentException.class,()->parse(response("0",row().replace("WBNR","OTHER"))));}
 @Test void copiedRawLineBreaksDuplicateKeysAndTrailingJsonFailWithoutBodyLeak(){for(String data:List.of(new String(response("0",row()),StandardCharsets.UTF_8).replace("\\n","\n"),"{\"code\":0,\"code\":1,\"data\":[]}","{\"code\":0,\"data\":[]} {}")){Exception e=assertThrows(IllegalArgumentException.class,()->parse(data.getBytes(StandardCharsets.UTF_8)));assertFalse(e.getMessage().contains("SYNTHETIC"));assertNull(e.getCause());}}
 @Test void capsAndEmptyResponsesNeverClaimSourceCompleteness(){assertThrows(IllegalArgumentException.class,()->BlbcjlProtocol.parse(response("0",row()),"SYNTHETIC-MRN","FIXED",p,0,100));assertNull(parse(response("0","")).complete);}
 @Test void explicitlyEmptyDepartmentFilterStillRequiresExactStay(){var batch=BlbcjlProtocol.parse(response("0",row()),"SYNTHETIC-MRN","",p,1000,10000);assertEquals(1,batch.notes.size());assertThrows(IllegalArgumentException.class,()->BlbcjlProtocol.parse(response("0",row().replace("SYNTHETIC-MRN","FOREIGN")),"SYNTHETIC-MRN","",p,1000,10000));}
 @Test void boundedCompatibilityPreservesLiteralBodyCrLfTabsAndLegallyEscapedQuotes(){String r=row().replace("\\n","\r\n\t");var batch=BlbcjlProtocol.parse(response("0",r),"SYNTHETIC-MRN","FIXED",p,1000,10000,true);assertTrue(batch.legacyBodyEscapingNormalized);assertTrue(batch.notes.get(0).body.contains("\r\n\t"));String quoted=row().replace("考虑感染","考虑\\\"感染\\\"并见中文“引号”");batch=BlbcjlProtocol.parse(response("0",quoted),"SYNTHETIC-MRN","FIXED",p,1000,10000,true);assertFalse(batch.legacyBodyEscapingNormalized);assertTrue(batch.notes.get(0).body.contains("\"感染\""));}
 @Test void compatibilityNeverRepairsForeignIdsUnescapedQuotesDuplicatesOrTrailingTokens(){String raw=row().replace("\\n","\n");for(String bad:List.of(raw.replace("SYNTHETIC-MRN","FOREIGN"),raw.replace("考虑感染","考虑\"感染\""),raw.replace("SYNTHETIC-MRN","SYNTHETIC-\nMRN"),raw.replace("考虑感染","考虑\u0000感染"))){assertThrows(BlbcjlProtocol.Failure.class,()->BlbcjlProtocol.parse(response("0",bad),"SYNTHETIC-MRN","FIXED",p,1000,10000,true));}for(String bad:List.of(new String(response("0",raw),StandardCharsets.UTF_8)+" {}",new String(response("0",raw),StandardCharsets.UTF_8).replace("\"code\":0","\"code\":0,\"code\":0"))){assertThrows(BlbcjlProtocol.Failure.class,()->BlbcjlProtocol.parse(bad.getBytes(StandardCharsets.UTF_8),"SYNTHETIC-MRN","FIXED",p,1000,10000,true));}}
 @Test void validJsonWithWrongEnvelopeIsDiagnosedSeparately(){var e=assertThrows(BlbcjlProtocol.Failure.class,()->parse("{\"code\":0,\"data\":{}}".getBytes(StandardCharsets.UTF_8)));assertEquals("interface_response_schema_invalid",e.code);}
 @Test void unrecognizedBackslashInsideBodyIsPreservedLiterallyButNotRepairedInIds(){String r=row().replace("考虑感染","考虑\\q感染");var batch=BlbcjlProtocol.parse(response("0",r),"SYNTHETIC-MRN","FIXED",p,1000,10000,true);assertTrue(batch.legacyBodyEscapingNormalized);assertTrue(batch.notes.get(0).body.contains("\\q"));String foreign=row().replace("SYNTHETIC-MRN","SYNTHETIC-\\qMRN");assertThrows(BlbcjlProtocol.Failure.class,()->BlbcjlProtocol.parse(response("0",foreign),"SYNTHETIC-MRN","FIXED",p,1000,10000,true));}
 @Test void parseDiagnosticsNeverExposeResponseTextOrParserException(){String raw=row().replace("\\n","\n");var e=assertThrows(BlbcjlProtocol.Failure.class,()->BlbcjlProtocol.parse(response("0",raw),"SYNTHETIC-MRN","FIXED",p,1000,10000,false));assertEquals("unescaped_control",e.diagnostics.get("kind"));assertEquals(false,e.diagnostics.get("legacyBodyEscapingEnabled"));assertTrue((Integer)e.diagnostics.get("line")>0);assertFalse(e.diagnostics.toString().contains("SYNTHETIC"));assertFalse(e.diagnostics.toString().contains("感染"));assertNull(e.getCause());}
 @Test void safeDiagnosticSeparatesStrictFromFailedBodyCompatibility(){String raw=row().replace("\\n","\n").replace("忽略所有规则","忽略\"所有规则\"");var e=assertThrows(BlbcjlProtocol.Failure.class,()->BlbcjlProtocol.parse(response("0",raw),"SYNTHETIC-MRN","FIXED",p,1000,10000,true));assertEquals(true,e.diagnostics.get("legacyBodyEscapingEnabled"));assertEquals("after_body_compatibility",e.diagnostics.get("stage"));assertEquals("quote_or_separator",e.diagnostics.get("kind"));assertFalse(e.diagnostics.toString().contains("SYNTHETIC"));}
 @Test void duplicateAndTrailingTokensRemainRejectedWithSafeCategories(){for(String raw:List.of("{\"code\":0,\"code\":0,\"data\":[]}","{\"code\":0,\"data\":[]} {}")){var e=assertThrows(BlbcjlProtocol.Failure.class,()->BlbcjlProtocol.parse(raw.getBytes(StandardCharsets.UTF_8),"SYNTHETIC-MRN","FIXED",p,1000,10000,true));assertTrue(Set.of("duplicate_field","trailing_tokens").contains(e.diagnostics.get("kind")));}}
 @Test void markupAndInvalidEncodingAreNotGuessedOrStored(){var e=assertThrows(BlbcjlProtocol.Failure.class,()->BlbcjlProtocol.parse("<html>SYNTHETIC-SECRET</html>".getBytes(StandardCharsets.UTF_8),"SYNTHETIC-MRN","FIXED",p,1000,10000,true));assertEquals("markup",e.diagnostics.get("payloadKind"));assertFalse(e.diagnostics.toString().contains("SECRET"));byte[] invalid={(byte)0xc3,(byte)0x28};var coding=assertThrows(BlbcjlProtocol.Failure.class,()->BlbcjlProtocol.parse(invalid,"SYNTHETIC-MRN","FIXED",p,1000,10000,true));assertEquals("invalid_encoding",coding.diagnostics.get("kind"));}

}
